question.solution:
def eat(page_fault_rate, mem_access_time, fault_time):
    return (1 - page_fault_rate) * mem_access_time + page_fault_rate * fault_time

def max_fault_rate(target_eat, mem_access_time, fault_time):
    if target_eat <= mem_access_time:
        return 0.0
    if target_eat >= fault_time:
        return 1.0
    return (target_eat - mem_access_time) / (fault_time - mem_access_time)

print(eat(0.001, 100, 10100))
print(max_fault_rate(300, 100, 10100))
print(eat(0, 100, 10100))
print(eat(1, 100, 10100))
